import joblib
import pandas as pd
import requests
import streamlit as st

# Page configuration
st.set_page_config(
    page_title="Purchase Intention Predictor",
    page_icon="🛒",
    layout="wide"
)

# FastAPI endpoint
API_URL = "http://127.0.0.1:8000/predict"

# App heading
st.title("🛒 Online Shoppers' Purchase Intention")
st.write(
    "Enter visitor session details to estimate the likelihood "
    "of a purchase."
)

st.info(
    "Predictions are generated by your FastAPI backend using "
    "your trained machine-learning model. This is an estimate, "
    "not a guarantee of a purchase."
)

# Input form
with st.form("visitor_form"):
    st.subheader("Visitor Session Details")

    col1, col2 = st.columns(2)

    with col1:
        administrative = st.number_input(
            "Administrative pages visited",
            min_value=0, value=0, step=1
        )
        administrative_duration = st.number_input(
            "Administrative time (seconds)",
            min_value=0.0, value=0.0
        )
        informational = st.number_input(
            "Informational pages visited",
            min_value=0, value=0, step=1
        )
        informational_duration = st.number_input(
            "Informational time (seconds)",
            min_value=0.0, value=0.0
        )
        product_related = st.number_input(
            "Product-related pages visited",
            min_value=0, value=5, step=1
        )
        product_related_duration = st.number_input(
            "Product-related time (seconds)",
            min_value=0.0, value=120.0
        )
        bounce_rates = st.number_input(
            "Bounce rate",
            min_value=0.0, max_value=1.0, value=0.02
        )
        exit_rates = st.number_input(
            "Exit rate",
            min_value=0.0, max_value=1.0, value=0.03
        )

    with col2:
        special_day = st.number_input(
            "Special day proximity",
            min_value=0.0, max_value=1.0, value=0.0
        )
        month = st.selectbox(
            "Month",
            [
                "Feb", "Mar", "May", "June", "Jul",
                "Aug", "Sep", "Oct", "Nov", "Dec"
            ]
        )
        operating_system = st.selectbox(
            "Operating system code", list(range(1, 9))
        )
        browser = st.selectbox(
            "Browser code", list(range(1, 14))
        )
        region = st.selectbox(
            "Region code", list(range(1, 10))
        )
        traffic_type = st.selectbox(
            "Traffic type code", list(range(1, 21))
        )
        visitor_type = st.selectbox(
            "Visitor type",
            ["Returning_Visitor", "New_Visitor", "Other"]
        )
        weekend = st.selectbox(
            "Is it a weekend?",
            [False, True],
            format_func=lambda x: "Yes" if x else "No"
        )

    submitted = st.form_submit_button(
        "Predict Purchase Intention",
        type="primary",
        use_container_width=True
    )

# Send visitor data to FastAPI
if submitted:
    visitor = {
        "Administrative": administrative,
        "Administrative_Duration": administrative_duration,
        "Informational": informational,
        "Informational_Duration": informational_duration,
        "ProductRelated": product_related,
        "ProductRelated_Duration": product_related_duration,
        "BounceRates": bounce_rates,
        "ExitRates": exit_rates,
        "SpecialDay": special_day,
        "Month": month,
        "OperatingSystems": operating_system,
        "Browser": browser,
        "Region": region,
        "TrafficType": traffic_type,
        "VisitorType": visitor_type,
        "Weekend": weekend,
    }

    try:
        with st.spinner("Requesting prediction from the ML API..."):
            response = requests.post(
                API_URL,
                json=visitor,
                timeout=15
            )
            response.raise_for_status()
            result = response.json()

        probability = result["purchase_probability"]
        probability_percent = result["purchase_probability_percent"]
        threshold = result["threshold"]
        prediction = result["predicted_purchase"]

        st.divider()
        st.subheader("Prediction Result")

        st.metric(
            "Estimated purchase probability",
            f"{probability_percent:.2f}%"
        )

        st.progress(max(0.0, min(1.0, float(probability))))

        if prediction:
            st.success(
                "The model predicts that this visitor is likely to purchase."
            )
        else:
            st.warning(
                "The model predicts that this visitor is less likely to purchase."
            )

        st.caption(
            f"Probability: {probability:.3f} | "
            f"Decision threshold: {threshold:.2f}"
        )

        st.info(result.get(
            "note",
            "This prediction is an estimate, not a guarantee."
        ))

    except requests.exceptions.ConnectionError:
        st.error(
            "Cannot connect to FastAPI. Start the backend in a separate "
            "terminal using: python -m uvicorn api:app --reload"
        )

    except requests.exceptions.Timeout:
        st.error(
            "The API request timed out. Check whether FastAPI is running "
            "and try again."
        )

    except requests.exceptions.HTTPError:
        try:
            error_detail = response.json().get(
                "detail", response.text
            )
        except ValueError:
            error_detail = response.text

        st.error(f"API error ({response.status_code}): {error_detail}")

    except (KeyError, ValueError) as exc:
        st.error(f"Could not interpret the API response: {exc}")

    except requests.exceptions.RequestException as exc:
        st.error(f"Request failed: {exc}")

st.divider()
st.caption(
    "Educational portfolio project. Predictions are estimates and "
    "should not be used as the sole basis for business decisions."
)
